import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        Locale locale = Locale.forLanguageTag(in.nextLine().trim());
        BigDecimal total = BigDecimal.ZERO;
        while (in.hasNextLine()) {
            total = total.add(new BigDecimal(in.nextLine().trim()));
        }
        System.out.println("Total: " + total);
    }
}

cards.solution:
import java.math.BigDecimal;
import java.text.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner in = new Scanner(System.in);
        Locale locale = Locale.forLanguageTag(in.nextLine().trim());
        BigDecimal total = BigDecimal.ZERO;
        while (in.hasNextLine()) {
            total = total.add(new BigDecimal(in.nextLine().trim()));
        }
        NumberFormat uang = NumberFormat.getCurrencyInstance(locale);
        System.out.println("Total: " + uang.format(total));
    }
}
